#include <vector>
#include <algorithm>

class Solution {
public:
    bool hasUniqueMiddleElement(std::vector<int>& nums) {
        int n = nums.size();
        if (n % 2 == 0) return false;
        int midVal = nums[n / 2];
        return std::count(nums.begin(), nums.end(), midVal) == 1;
    }
};

class Solution {
    public boolean hasUniqueMiddleElement(int[] nums) {
        int n = nums.length;
        if (n % 2 == 0) return false;
        int midVal = nums[n / 2];
        int count = 0;
        for (int x : nums) {
            if (x == midVal) count++;
        }
        return count == 1;
    }
}

